@spec patternEditor_shelf_spec  src=tests/specs/patternEditor_shelf_spec.lua  loc=238  sha=untracked  cases=5
@exercises patternEditor (pe), dataStore (h.ds)
@surface   pe:open, pe:draw, pe:handleInput, ds:get, ds:assign
@harness   mk, reaper.GetMediaItemTake_Track

# Intent
  design/fx-patterns.md P4: the library copy shelf -- Save/Load in the pattern-editor toolbar.
  Drives the real drawToolbar (Save popup) and drawLoad (picker) against a fake imgui; gridPane is
  swapped for an inert stub via util._stubs so pe:draw's toolbar runs without the grid render.

# Helpers
  @fn keyId(name)  @ 11-20
  @fn setKeys(keys, mods)  @ 62-65
  @fn loadPE(deps)  @ 82-91
  @fn notesBody()  @ 93-101
  @fn curveBody()  @ 103-108
  @fn withEditor(harness, body)  @ 112-119
      -- Open the editor on `body`, capturing each write-through commit; get() reads the latest. hostDs is
      -- the harness ds (project scope), standing in for trackerPage's shared ds.
  @fn frame(pe, o)  @ 122-127
      -- One draw frame: queue a button press / injected input text / held keys, then draw.
  @fn input(pe, keys)  @ 129-132

# Cases
  @case 'Save stores a whitelisted copy on the host ds under the name'  [harness]  @ 136-147
  @case 'Save over a divergent name confirms; n leaves the shelf, y overwrites'  [harness]  @ 151-170
  @case 'Load rematerialises the picked body; the param tracks it'  [harness]  @ 174-190
  @case 'the picker offers only matching kind, and matching domain for curves'  [harness]  @ 194-217
  @case 'Esc after a Load restores the modal-open snapshot, not the loaded body'  [harness]  @ 221-236

